// Parameter metadata matched to the connected vehicle and its firmware version, from ArduPilot's
// ParameterRepository (https://github.com/ArduPilot/ParameterRepository): one apm.pdef.json per vehicle and
// major.minor version, generated by ArduPilot's CI from the newest release tag of that version. The newest
// version folder for each vehicle is generated from the development branch.
//
// This file holds the pure parts (version parsing, which folders to try, parsing the JSON); the loading and
// caching live in store/paramMetaStore.ts.

import type { VehicleCategory } from './messages';
import type { ParamMeta } from './paramMetadata';

export const PARAM_REPO_BASE = 'https://raw.githubusercontent.com/ArduPilot/ParameterRepository/main';

/** The repository's folder prefix for a vehicle category, or null when it has none. */
export function repoVehicleName(category: VehicleCategory): string | null {
  switch (category) {
    case 'copter':
      return 'Copter';
    case 'plane':
      return 'Plane';
    case 'rover':
      return 'Rover';
    case 'sub':
      return 'Sub';
    case 'tracker':
      return 'Tracker';
    default:
      return null;
  }
}

export type FirmwareReleaseType = 'official' | 'dev' | 'alpha' | 'beta' | 'rc';

export interface FirmwareVersion {
  major: number;
  minor: number;
  patch: number;
  type: FirmwareReleaseType;
}

/**
 * Reads "4.6.2", "4.8.0-dev", "4.5.0-beta2", "4.6.0-rc1" or "V4.6.2" (from AUTOPILOT_VERSION or the boot
 * banner). Returns null for anything without at least major.minor.
 */
export function parseFirmwareVersion(text: string | null | undefined): FirmwareVersion | null {
  if (!text) return null;
  const m = text.trim().match(/^[Vv]?(\d+)\.(\d+)(?:\.(\d+))?(?:[-_ ]?(dev|alpha|beta|rc)\w*)?/i);
  if (!m) return null;
  const type = (m[4]?.toLowerCase() as FirmwareReleaseType | undefined) ?? 'official';
  return { major: Number(m[1]), minor: Number(m[2]), patch: m[3] ? Number(m[3]) : 0, type };
}

export interface CatalogCandidate {
  /** Folder name, e.g. "Rover-4.6". */
  folder: string;
  url: string;
  major: number;
  minor: number;
  /**
   * How well this folder matches the firmware:
   * - exact: same major.minor as a release (or beta / rc) build;
   * - dev-same-minor: a development build, matched to the folder of the same major.minor. When that version is
   *   still in development the folder is generated from the development branch, so it is the dev metadata; once
   *   the version is released it is that release's metadata. Either way it is close, not guaranteed identical;
   * - earlier: the firmware's own version isn't published (too new, or a gap), so the nearest earlier one.
   */
  match: 'exact' | 'dev-same-minor' | 'earlier';
}

/** Highest minor version tried when stepping back across a major version (e.g. from 5.0 to 4.x). */
const MAX_MINOR_ACROSS_MAJOR = 9;
/** Folders tried in all, so a version far beyond what's published doesn't probe forever. */
const MAX_CANDIDATES = 12;

/**
 * The folders to try, best first: the firmware's own major.minor, then earlier minors (and the previous major's),
 * for versions the repository doesn't have yet or skipped (it has no Rover-4.3 or Sub-4.6, for example).
 */
export function catalogCandidates(vehicle: string, version: FirmwareVersion): CatalogCandidate[] {
  const out: CatalogCandidate[] = [];
  const push = (major: number, minor: number, match: CatalogCandidate['match']) => {
    const folder = `${vehicle}-${major}.${minor}`;
    out.push({ folder, url: `${PARAM_REPO_BASE}/${folder}/apm.pdef.json`, major, minor, match });
  };
  push(version.major, version.minor, version.type === 'dev' ? 'dev-same-minor' : 'exact');
  for (let minor = version.minor - 1; minor >= 0 && out.length < MAX_CANDIDATES; minor--) push(version.major, minor, 'earlier');
  for (let minor = MAX_MINOR_ACROSS_MAJOR; minor >= 0 && out.length < MAX_CANDIDATES && version.major > 0; minor--) {
    push(version.major - 1, minor, 'earlier');
  }
  return out;
}

/** A sentence for the editor saying which metadata is in use and how closely it matches. */
export function describeCatalogMatch(vehicle: string, version: FirmwareVersion, used: CatalogCandidate): string {
  const fw = `${version.major}.${version.minor}.${version.patch}${version.type === 'official' ? '' : `-${version.type}`}`;
  const meta = `${vehicle} ${used.major}.${used.minor}`;
  if (used.match === 'exact') return `${meta} parameter metadata, matching firmware ${fw}.`;
  if (used.match === 'dev-same-minor') {
    return `${meta} parameter metadata for development firmware ${fw}: ArduPilot's ${used.major}.${used.minor} metadata, which tracks the development branch while ${used.major}.${used.minor} is in development. A dev build can still differ slightly.`;
  }
  return `${meta} parameter metadata: the nearest published version to firmware ${fw}, so some parameters may be missing or differ.`;
}

const num = (v: unknown): number | undefined => {
  const n = typeof v === 'number' ? v : typeof v === 'string' && v.trim() !== '' ? Number(v) : NaN;
  return Number.isFinite(n) ? n : undefined;
};

const numberKeyed = (obj: unknown): Record<number, string> | undefined => {
  if (!obj || typeof obj !== 'object') return undefined;
  const out: Record<number, string> = {};
  for (const [k, v] of Object.entries(obj as Record<string, unknown>)) {
    const n = num(k);
    if (n !== undefined && typeof v === 'string') out[n] = v;
  }
  return Object.keys(out).length ? out : undefined;
};

const isTrue = (v: unknown) => v === true || (typeof v === 'string' && v.toLowerCase() === 'true');

/**
 * Turns an apm.pdef.json into name → metadata. The file is grouped by vehicle ("Rover") and library ("BATT_",
 * "SERIAL", "SERVO9_", …), with each parameter under its full name; every group is read. Range is
 * {low, high} and Values / Bitmask are keyed by strings, all as text.
 */
export function parsePdefJson(json: unknown): Record<string, ParamMeta> {
  const out: Record<string, ParamMeta> = {};
  if (!json || typeof json !== 'object') return out;
  for (const [group, params] of Object.entries(json as Record<string, unknown>)) {
    if (group === 'json' || !params || typeof params !== 'object') continue;
    for (const [rawName, raw] of Object.entries(params as Record<string, any>)) {
      if (!raw || typeof raw !== 'object') continue;
      const name = (rawName.includes(':') ? rawName.split(':').pop()! : rawName).toUpperCase();
      const meta: ParamMeta = { description: typeof raw.Description === 'string' ? raw.Description.trim() : '' };
      if (typeof raw.DisplayName === 'string' && raw.DisplayName.trim()) meta.displayName = raw.DisplayName.trim();
      if (typeof raw.Units === 'string' && raw.Units.trim()) meta.units = raw.Units.trim();
      const low = num(raw.Range?.low);
      const high = num(raw.Range?.high);
      if (low !== undefined) meta.min = low;
      if (high !== undefined) meta.max = high;
      const inc = num(raw.Increment);
      if (inc !== undefined && inc > 0) meta.increment = inc;
      const values = numberKeyed(raw.Values);
      if (values) meta.values = values;
      const bitmask = numberKeyed(raw.Bitmask);
      if (bitmask) meta.bitmask = bitmask;
      if (isTrue(raw.RebootRequired)) meta.rebootRequired = true;
      if (isTrue(raw.ReadOnly)) meta.readOnly = true;
      if (raw.User === 'Standard' || raw.User === 'Advanced') meta.user = raw.User;
      out[name] = meta;
    }
  }
  return out;
}
